export function issue(register: Register, notice: Notice): void {
  const before = register.notices.slice();
  const at = before.findIndex((n) => n.ref === notice.ref);
  // Anything the original rules refuse is refused here too, with the register untouched.
  issueOnTop(register, notice);
  if (at < 0) return;
  const added = register.notices.filter((n) => !before.includes(n));
  if (added.length === 0) return;
  const result = before.slice();
  result.splice(at, 1, added[0]);
  register.notices.splice(0, register.notices.length, ...result);
}

